<original_code>
import java.io.*;
import java.util.*;

public class Task {

    static final int MOD = 1000000007;

    public static void main(String[] args) throws Exception {
        Scanner in;
        PrintWriter out;
        try {
            in = new Scanner(new File("input.txt"));
            out = new PrintWriter(new BufferedWriter(new FileWriter("output.txt")));
        } catch (Exception e) {
            in = new Scanner(System.in);
            out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        }

        int n = in.nextInt();
        int total = 2 * n;
        int[][] dp = new int[total][n + 1];
        dp[0][1] = 1;

        for (int i = 1; i < total; i++) {
            for (int j = 0; j <= n; j++) {
                int v = dp[i - 1][j];
                if (j + 1 <= n) {
                    dp[i][j + 1] = (dp[i][j + 1] + v) % MOD;
                }
                if (j - 1 >= 0) {
                    dp[i][j - 1] = (dp[i][j - 1] + v) % MOD;
                }
            }
        }

        int ans = 0;
        for (int i = total - 2; i >= 0; i -= 2) {
            for (int j = 0; j <= n; j++) {
                if ((j & 1) == 1 && j <= total - 1 - i) {
                    ans = (ans + dp[i][j]) % MOD;
                }
            }
        }

        out.print(ans);
        out.flush();
        out.close();
    }
}
